def oxford_join_numbers(numbers):
    if not numbers:
        return ""
    elif len(numbers) == 1:
        return str(numbers[0])
    elif len(numbers) == 2:
        return f"{numbers[0]} and {numbers[1]}"
    else:
        return ", ".join(str(n) for n in numbers[:-1]) + ", and " + str(numbers[-1])
